const data = JSON.parse(output);
const design = data.designIntelligence;
const lineageValid = Array.isArray(design?.formLineageHypotheses) && design.formLineageHypotheses.every((item) => Array.isArray(item.visualBasis) && typeof item.alternativeExplanation === 'string' && Array.isArray(item.verificationQueries) && typeof item.confidence === 'number');
const directionsValid = Array.isArray(design?.recommendedDirections) && design.recommendedDirections.every((item) => ['设计手法', '设计语言'].includes(item.directionType) && Array.isArray(item.transferableMechanisms) && Array.isArray(item.searchQueries));
const referencesValid = Array.isArray(design?.referenceCandidates) && design.referenceCandidates.every((item) => Array.isArray(item.sharedMechanisms) && Array.isArray(item.avoidCopying) && Array.isArray(item.verificationQueries) && ['视觉类比', '知识候选'].includes(item.evidenceType));
const valid = Boolean(
  data.title &&
  data.subject?.primary &&
  data.formStructure?.overallSilhouette &&
  Array.isArray(design?.designLanguage) &&
  Array.isArray(design?.designTechniques) &&
  lineageValid &&
  Array.isArray(design?.analogousStrategies) &&
  Array.isArray(design?.transferablePrinciples) &&
  directionsValid &&
  referencesValid &&
  Array.isArray(data.cmfAnalysis?.materialZones) &&
  Array.isArray(data.cmfAnalysis?.finishZones) &&
  data.cmfAnalysis?.evidenceBoundary &&
  data.reconstruction?.positivePrompt
);
return valid || '缺少主体、造型、设计语言、设计手法、推荐方向、参考候选、CMF、证据边界或重建提示词字段';
